import { Check, ShieldCheck } from "lucide-react";
import { ChatIcon } from "./icon";
import type { JsonValue, RenderApproval } from "@agentdock-ai/ui-core";
import { ErrorState } from "./error-state";
import { Button } from "./ui/button";
export function ApprovalCard({
  approval,
  enabled,
  pending,
  error,
  onRespond,
}: {
  approval: RenderApproval;
  enabled: boolean;
  pending: boolean;
  error?: string;
  onRespond: (decisions: readonly JsonValue[]) => void;
}) {
  const resolved = approval.state === "resolved";
  return (
    <section
      aria-label={approval.title}
      className="min-w-0 rounded-lg border border-border bg-card/30 p-3"
    >
      <div className="flex items-center gap-2.5">
        <span className="flex size-6 items-center justify-center rounded-lg bg-muted">
          {resolved ? (
            <ChatIcon icon={Check} size={14} aria-hidden="true" />
          ) : (
            <ChatIcon icon={ShieldCheck} size={14} aria-hidden="true" />
          )}
        </span>
        <h3 className="text-[13px] font-medium">
          {resolved ? "Response received" : approval.title}
        </h3>
      </div>
      <p className="mt-3 whitespace-pre-wrap text-[13px] leading-6 text-muted-foreground [overflow-wrap:anywhere]">
        {approval.detail}
      </p>
      {error && (
        <div className="mt-3">
          <ErrorState title="Response not confirmed" detail={error} />
        </div>
      )}
      {!resolved && (
        <>
          <div className="mt-3 flex flex-wrap gap-2">
            {approval.actions.map((action) => (
              <Button
                key={action.id}
                variant="outline"
                disabled={!enabled || pending}
                onClick={() => onRespond([action.input])}
              >
                {action.label}
              </Button>
            ))}
          </div>
          <p className="mt-3 text-xs leading-5 text-muted-foreground">
            {pending
              ? "Sending your response…"
              : !enabled
                ? "This app can’t respond to this request here."
                : approval.actions.length === 0
                  ? "Continue this request in the app."
                  : "The agent is paused until you respond."}
          </p>
        </>
      )}
    </section>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import { Check, Copy } from "lucide-react";
import { ChatIcon } from "./icon";
import { Button } from "./ui/button";
export function ChatActionBar({ text }: { text: string }) {
  const [status, setStatus] = useState("");
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  return (
    <div className="mt-1.5 flex items-center gap-2 text-xs text-muted-foreground">
      <Button
        aria-label={status === "Copied" ? "Answer copied" : "Copy answer"}
        title="Copy answer"
        className="size-7 min-h-7 px-0 opacity-60 hover:opacity-100 focus-visible:opacity-100"
        onClick={async () => {
          try {
            await navigator.clipboard.writeText(text);
            setStatus("Copied");
          } catch {
            setStatus("Copy unavailable. Select the text to copy.");
          }
          clearTimeout(timer.current);
          timer.current = setTimeout(() => setStatus(""), 2500);
        }}
      >
        {status === "Copied" ? (
          <ChatIcon icon={Check} size={14} aria-hidden="true" />
        ) : (
          <ChatIcon icon={Copy} size={14} aria-hidden="true" />
        )}
      </Button>
      <span role="status">{status}</span>
    </div>
  );
}

import type { ReactNode } from "react";
import { cn } from "./utils";
export function ChatShell({
  children,
  footer,
  className,
  empty = false,
}: {
  children: ReactNode;
  footer: ReactNode;
  className?: string;
  empty?: boolean;
}) {
  return (
    <section
      aria-label="Agent conversation"
      className={cn(
        "relative flex h-full min-h-0 w-full min-w-0 flex-col bg-background font-sans text-[14px] text-foreground antialiased",
        empty ? "overflow-y-auto" : "overflow-hidden",
        className,
      )}
    >
      <div className={empty ? "hidden" : "contents"}>{children}</div>
      <div
        className={cn(
          "z-10 shrink-0 bg-background px-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
          empty ? "my-auto w-full py-8" : "pt-2 sm:pb-5",
        )}
      >
        <div className="mx-auto w-full max-w-[42rem]">{footer}</div>
      </div>
    </section>
  );
}

"use client";
import { useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { ScrollToLatest } from "./scroll-to-latest";

export function ChatViewport({
  children,
  revision,
  latestUserId,
  empty,
}: {
  children: ReactNode;
  revision: unknown;
  latestUserId?: string;
  empty: boolean;
}) {
  const viewport = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const following = useRef(true);
  const previousUser = useRef(latestUserId);
  const lastScroll = useRef(0);
  const [showLatest, setShowLatest] = useState(false);
  function toBottom() {
    const el = viewport.current;
    if (!el) return;
    following.current = true;
    el.scrollTo({ top: el.scrollHeight, behavior: "instant" });
    lastScroll.current = el.scrollTop;
    setShowLatest(false);
  }
  useLayoutEffect(() => {
    const el = viewport.current;
    if (!el) return;
    if (previousUser.current !== latestUserId) {
      previousUser.current = latestUserId;
      following.current = true;
      const rows = el.querySelectorAll<HTMLElement>('[data-role="user"]');
      const row = rows.item(rows.length - 1);
      if (row) el.scrollTop = row.offsetTop - 24;
      lastScroll.current = el.scrollTop;
      setShowLatest(false);
    } else if (following.current) {
      el.scrollTop = el.scrollHeight;
      lastScroll.current = el.scrollTop;
    } else setShowLatest(el.scrollHeight - el.scrollTop - el.clientHeight > 48);
  }, [revision, latestUserId]);
  useLayoutEffect(() => {
    if (!viewport.current || !content.current) return;
    const observer = new ResizeObserver(() => {
      if (following.current && viewport.current) {
        viewport.current.scrollTop = viewport.current.scrollHeight;
        lastScroll.current = viewport.current.scrollTop;
      }
    });
    observer.observe(viewport.current);
    observer.observe(content.current);
    return () => observer.disconnect();
  }, []);
  return (
    <div className="relative flex min-h-0 flex-1 flex-col">
      <div
        ref={viewport}
        tabIndex={0}
        role="region"
        aria-label="Conversation messages"
        className="relative min-h-0 flex-1 overflow-x-hidden overflow-y-auto overscroll-contain outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring [overflow-anchor:none] [scrollbar-gutter:stable]"
        onScroll={() => {
          const el = viewport.current!;
          const nearBottom =
            el.scrollHeight - el.scrollTop - el.clientHeight < 48;
          if (el.scrollTop < lastScroll.current - 1) following.current = false;
          else if (nearBottom) following.current = true;
          lastScroll.current = el.scrollTop;
          if (nearBottom) setShowLatest(false);
        }}
        onClickCapture={(event) => {
          // Expanding a disclosure should preserve the reader's place.
          if (
            event.target instanceof Element &&
            event.target.closest("[aria-expanded]")
          )
            following.current = false;
        }}
        onKeyDownCapture={(event) => {
          if (
            event.key === "PageUp" ||
            event.key === "Home" ||
            event.key === "ArrowUp"
          )
            following.current = false;
        }}
      >
        <div ref={content} className={cnContent(empty)}>
          {children}
        </div>
      </div>
      {showLatest && <ScrollToLatest onClick={toBottom} />}
    </div>
  );
}
function cnContent(empty: boolean) {
  return `mx-auto flex w-full max-w-[44rem] flex-col px-4 pt-6 pb-8 sm:px-4 ${empty ? "min-h-full justify-center" : "gap-6 pb-10"}`;
}

"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { MessagesSquare, PanelLeft, X } from "lucide-react";
import { ChatIcon } from "./icon";
import { cn } from "./utils";
export function ChatWorkspace({
  children,
  sidebar,
  title = "New chat",
  brand = "Agentdock",
  actions,
  className,
}: {
  children: ReactNode;
  sidebar: ReactNode;
  title?: string;
  brand?: string;
  actions?: ReactNode;
  className?: string;
}) {
  const [expanded, setExpanded] = useState(true);
  const mobile = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    mobile.current?.close();
  }, [title]);
  const brandRow = (
    <div className="flex h-12 shrink-0 items-center justify-between gap-2 border-b border-border px-4 text-[13px]">
      <span className="flex items-center gap-2">
        <ChatIcon icon={MessagesSquare} size={16} aria-hidden="true" />
        {brand}
      </span>
      <button
        type="button"
        aria-label="Collapse thread sidebar"
        onClick={() => setExpanded(false)}
        className="flex size-7 items-center justify-center rounded-md text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
      >
        <ChatIcon icon={PanelLeft} size={14} />
      </button>
    </div>
  );
  return (
    <div
      className={cn(
        "flex h-full min-h-0 w-full overflow-hidden rounded-md border border-border bg-background font-sans text-foreground antialiased",
        className,
      )}
    >
      {expanded && (
        <aside
          aria-label="Thread sidebar"
          className="hidden w-60 shrink-0 flex-col border-r border-border bg-muted/70 md:flex"
        >
          {brandRow}
          <div className="min-h-0 flex-1">{sidebar}</div>
        </aside>
      )}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        <header className="flex h-12 shrink-0 items-center justify-between gap-3 border-b border-border px-4 sm:px-5">
          <div className="flex min-w-0 items-center gap-3">
            <button
              type="button"
              aria-label="Open thread sidebar"
              onClick={() => {
                if (matchMedia("(min-width: 768px)").matches) setExpanded(true);
                else mobile.current?.showModal();
              }}
              className={cn(
                "flex size-7 items-center justify-center rounded-md text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring",
                expanded && "md:hidden",
              )}
            >
              <ChatIcon icon={PanelLeft} size={15} />
            </button>
            <span className="truncate text-[13px]">{title}</span>
          </div>
          <div className="flex shrink-0 items-center gap-1 text-xs text-muted-foreground">
            {actions}
          </div>
        </header>
        <main className="flex min-h-0 min-w-0 flex-1 flex-col">{children}</main>
      </div>
      <dialog
        ref={mobile}
        aria-label="Thread sidebar"
        className="fixed inset-y-0 left-0 right-auto m-0 h-dvh max-h-none w-[min(19rem,85vw)] max-w-none border-0 border-r border-border bg-background p-0 text-foreground backdrop:bg-black/40"
      >
        <div className="flex h-full min-h-0 flex-col bg-muted/30">
          <div className="flex h-12 shrink-0 items-center justify-between border-b border-border px-4 text-[13px]">
            <span>{brand}</span>
            <button
              type="button"
              aria-label="Close thread sidebar"
              onClick={() => mobile.current?.close()}
              className="flex size-7 items-center justify-center rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <ChatIcon icon={X} size={15} />
            </button>
          </div>
          <div
            className="min-h-0 flex-1"
            onClick={(event) => {
              if (
                event.target instanceof Element &&
                event.target.closest("button")
              )
                mobile.current?.close();
            }}
          >
            {sidebar}
          </div>
        </div>
      </dialog>
    </div>
  );
}

"use client";
import { useState } from "react";
import {
  AgentProvider,
  useAgentActions,
  useAgentState,
} from "@agentdock-ai/react";
import type { ChatProps } from "./types";
import { ChatShell } from "./chat-shell";
import { ChatViewport } from "./chat-viewport";
import { MessageList } from "./message-list";
import { EmptyState, Suggestions } from "./empty-state";
import { Composer } from "./composer";
import { ErrorState } from "./error-state";
import { Button } from "./ui/button";
import { useChatAttachments } from "./use-chat-attachments";

export function Chat(props: ChatProps) {
  return (
    <AgentProvider store={props.store}>
      <ChatSurface {...props} />
    </AgentProvider>
  );
}
function ChatSurface({
  adapter,
  className,
  disabled,
  showReasoning = true,
  suggestions,
  welcomeTitle,
  welcomeDescription,
  placeholder,
}: ChatProps) {
  const { renderModel: model, agent, streamStatus } = useAgentState();
  const actions = useAgentActions(adapter);
  const [draft, setDraft] = useState("");
  const attachments = useChatAttachments(adapter.attachments);
  const active =
    actions.busy ||
    (streamStatus === "consuming" &&
      !["completed", "failed", "cancelled"].includes(agent.status));
  const waiting = agent.status === "waiting" && streamStatus !== "stopped";
  const paused = waiting && agent.interrupts.length === 0;
  const items = model.turns.at(-1)?.items ?? [];
  const activity = items.some(
    (item) =>
      (item.type === "tool-call" && item.active) ||
      (item.type === "tool-timeline" &&
        item.tools.some((tool) => tool.active)) ||
      (item.type === "approval" && item.approval.state === "pending") ||
      (item.type === "message" &&
        item.role === "assistant" &&
        showReasoning &&
        item.blocks.some(
          (b) => b.type === "reasoning" && b.state === "streaming",
        )),
  );
  const empty = model.turns.length === 0;
  const latestUser = model.turns
    .flatMap((turn) => turn.items)
    .filter((item) => item.type === "message" && item.role === "user")
    .at(-1);
  const latestUserId =
    latestUser?.type === "message" ? latestUser.messageId : undefined;
  async function submit(text: string) {
    if (
      disabled ||
      active ||
      waiting ||
      attachments.blocked ||
      (!text.trim() && attachments.items.length === 0)
    )
      return;
    const sent = attachments.take();
    setDraft("");
    const successful = await actions.sendMessage(
      text,
      sent.flatMap((item) => (item.attachment ? [item.attachment] : [])),
    );
    if (!successful) {
      setDraft((current) => current || text);
      attachments.restore(sent);
    }
  }
  let status = "";
  if (actions.cancelling) status = "Stopping…";
  else if (actions.respondingTo) status = "Sending response…";
  else if (paused) status = "Run paused";
  else if (waiting) status = "Waiting for your response";
  else if (active) status = "Agent is working";
  else if (streamStatus === "error") status = "Connection interrupted";
  else if (streamStatus === "stopped") status = "Stream stopped";
  else if (agent.status === "completed") status = "Response complete";
  else if (agent.status === "failed") status = "Run failed";
  else if (agent.status === "cancelled") status = "Run stopped";
  return (
    <ChatShell
      className={className}
      empty={empty}
      footer={
        <>
          {empty && (
            <EmptyState title={welcomeTitle} description={welcomeDescription} />
          )}
          <Composer
            key="composer"
            value={draft}
            onChange={setDraft}
            onSubmit={() => {
              void submit(draft);
            }}
            onStop={
              actions.canCancel && agent.runId
                ? () => {
                    void actions.cancelRun();
                  }
                : undefined
            }
            busy={active}
            waiting={waiting}
            cancelling={actions.cancelling}
            disabled={disabled}
            placeholder={placeholder}
            attachments={attachments.items}
            attachmentAccept={adapter.attachments?.accept}
            attachmentError={attachments.error}
            attachmentBlocked={attachments.blocked}
            onFiles={adapter.attachments ? attachments.add : undefined}
            onRemoveAttachment={attachments.remove}
            onRetryAttachment={attachments.retry}
          />
          {empty && suggestions && (
            <Suggestions
              suggestions={suggestions}
              disabled={disabled || active}
              onSubmit={(text) => {
                void submit(text);
              }}
            />
          )}
          <span
            role="status"
            aria-live="polite"
            aria-atomic="true"
            className="sr-only"
          >
            {status}
          </span>
        </>
      }
    >
      <ChatViewport revision={model} latestUserId={latestUserId} empty={empty}>
        {!empty && (
          <MessageList
            model={model}
            thinking={active && !waiting && !activity}
            showReasoning={showReasoning}
            canRespond={
              actions.canRespond &&
              !active &&
              !disabled &&
              streamStatus !== "stopped"
            }
            respondingTo={actions.respondingTo}
            approvalError={
              actions.actionError?.scope === "approval"
                ? actions.actionError.message
                : undefined
            }
            onRespond={(id, decisions) => {
              void actions.respondToInterrupt(id, decisions);
            }}
          />
        )}
        {paused && (
          <div
            role="status"
            className="mx-auto w-full max-w-[44rem] px-4 py-3 text-[13px] text-muted-foreground"
          >
            <p>
              {actions.canContinue
                ? "The run is paused. Continue when you’re ready."
                : "The run is paused. Continue it in your app."}
            </p>
            {actions.canContinue && (
              <Button
                className="mt-2"
                disabled={active || disabled}
                onClick={() => {
                  void actions.continueRun();
                }}
              >
                {active ? "Continuing…" : "Continue run"}
              </Button>
            )}
          </div>
        )}
        {model.transportError &&
          actions.actionError?.scope !== "approval" &&
          actions.actionError?.scope !== "continue" && (
            <ErrorState {...model.transportError} />
          )}
        {actions.actionError?.scope === "cancel" && (
          <ErrorState
            title="Unable to stop"
            detail={actions.actionError.message}
          />
        )}
        {actions.actionError?.scope === "continue" && (
          <ErrorState
            title="Unable to continue"
            detail={actions.actionError.message}
          />
        )}
      </ChatViewport>
    </ChatShell>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import { Paperclip, Image, Plus } from "lucide-react";
import { ChatIcon } from "./icon";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from "./ui/dropdown-menu";

export function ComposerAttachmentPicker({
  accept,
  disabled,
  onFiles,
}: {
  accept?: string;
  disabled?: boolean;
  onFiles: (files: readonly File[]) => void;
}) {
  const files = useRef<HTMLInputElement>(null);
  const images = useRef<HTMLInputElement>(null);
  const [open, setOpen] = useState(false);
  useEffect(() => {
    if (disabled) setOpen(false);
  }, [disabled]);
  const imageAccept = accept
    ? accept
        .split(",")
        .filter((type) => type.trim().startsWith("image/"))
        .join(",")
    : "image/*";
  const select = (input: HTMLInputElement) => {
    onFiles(Array.from(input.files ?? []));
    input.value = "";
  };
  const itemStyle =
    "flex min-h-9 cursor-pointer items-center gap-3 rounded-md px-2.5 py-2 text-[13px] outline-none data-[highlighted]:bg-muted focus:bg-muted data-[disabled]:pointer-events-none data-[disabled]:opacity-40";
  return (
    <div className="mr-auto flex items-center gap-0.5">
      <input
        ref={files}
        type="file"
        multiple
        accept={accept}
        aria-label="Choose files"
        hidden
        onChange={(event) => select(event.currentTarget)}
      />
      <input
        ref={images}
        type="file"
        multiple
        accept={imageAccept}
        aria-label="Choose images"
        hidden
        onChange={(event) => select(event.currentTarget)}
      />
      <DropdownMenu
        open={open && !disabled}
        onOpenChange={setOpen}
        modal={false}
      >
        <DropdownMenuTrigger
          type="button"
          aria-label="Add attachments"
          title="Add attachments"
          disabled={disabled}
          className="flex size-7 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-40 [@media(pointer:coarse)]:size-9"
        >
          <ChatIcon icon={Plus} size={18} />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          aria-label="Attachments"
          className="z-50 w-60 max-w-[calc(100vw-1.5rem)] rounded-xl border border-border bg-background p-1.5 text-foreground shadow-md"
        >
          {imageAccept && (
            <DropdownMenuItem
              disabled={disabled}
              onClick={() => images.current?.click()}
              className={itemStyle}
            >
              <ChatIcon
                icon={Image}
                size={16}
                className="text-muted-foreground"
              />
              Add photos
            </DropdownMenuItem>
          )}
          <DropdownMenuItem
            disabled={disabled}
            onClick={() => files.current?.click()}
            className={itemStyle}
          >
            <ChatIcon
              icon={Paperclip}
              size={16}
              className="text-muted-foreground"
            />
            Attach files
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

import { FileText, LoaderCircle, RotateCw, X } from "lucide-react";
import { ChatIcon } from "./icon";
import type { AttachmentDraft } from "./use-chat-attachments";

export function ComposerAttachments({
  items,
  onRemove,
  onRetry,
}: {
  items: readonly AttachmentDraft[];
  onRemove: (id: string) => void;
  onRetry: (id: string) => void;
}) {
  return (
    <ul
      aria-label="Message attachments"
      className="flex flex-wrap gap-2 px-1 pb-2 pt-1"
    >
      {items.map((item) => (
        <li
          key={item.id}
          className="flex min-w-0 max-w-full items-center gap-2 rounded-lg border border-border bg-background/50 p-1.5"
        >
          {item.previewUrl ? (
            <img
              src={item.previewUrl}
              alt=""
              className="size-8 rounded-md object-cover"
            />
          ) : (
            <span className="flex size-8 shrink-0 items-center justify-center rounded-md bg-muted">
              <ChatIcon icon={FileText} size={16} />
            </span>
          )}
          <div className="min-w-0 max-w-44">
            <p className="truncate text-xs leading-4" title={item.file.name}>
              {item.file.name}
            </p>
            <p
              role="status"
              className={`text-[10px] leading-4 ${item.status === "error" ? "text-destructive" : "text-muted-foreground"}`}
            >
              {item.status === "uploading"
                ? "Uploading…"
                : item.status === "error"
                  ? item.error || "Upload failed"
                  : `${Math.max(1, Math.round(item.file.size / 1_000))} KB`}
            </p>
          </div>
          {item.status === "uploading" && (
            <ChatIcon
              icon={LoaderCircle}
              size={12}
              className="motion-safe:animate-spin text-muted-foreground"
            />
          )}
          {item.status === "error" && (
            <button
              type="button"
              aria-label={`Retry upload ${item.file.name}`}
              onClick={() => onRetry(item.id)}
              className="flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
            >
              <ChatIcon icon={RotateCw} size={12} />
            </button>
          )}
          <button
            type="button"
            aria-label={`Remove attachment ${item.file.name}`}
            onClick={() => onRemove(item.id)}
            className="flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
          >
            <ChatIcon icon={X} size={12} />
          </button>
        </li>
      ))}
    </ul>
  );
}

"use client";
import { useId, useLayoutEffect, useRef } from "react";
import { ArrowUp, Square } from "lucide-react";
import { ChatIcon } from "./icon";
import { Button } from "./ui/button";
import { Textarea } from "./ui/textarea";
import { ComposerAttachmentPicker } from "./composer-attachment-picker";
import { ComposerAttachments } from "./composer-attachments";
import type { AttachmentDraft } from "./use-chat-attachments";
export function Composer({
  value,
  onChange,
  onSubmit,
  onStop,
  busy,
  waiting,
  cancelling,
  disabled,
  attachments = [],
  attachmentAccept,
  attachmentError,
  attachmentBlocked,
  onFiles,
  onRemoveAttachment,
  onRetryAttachment,
  placeholder = "Send a message…",
}: {
  value: string;
  onChange: (text: string) => void;
  onSubmit: () => void;
  onStop?: () => void;
  busy: boolean;
  waiting: boolean;
  cancelling: boolean;
  disabled?: boolean;
  attachments?: readonly AttachmentDraft[];
  attachmentAccept?: string;
  attachmentError?: string;
  attachmentBlocked?: boolean;
  onFiles?: (files: readonly File[]) => void;
  onRemoveAttachment?: (id: string) => void;
  onRetryAttachment?: (id: string) => void;
  placeholder?: string;
}) {
  const input = useRef<HTMLTextAreaElement>(null);
  const composing = useRef(false);
  const hint = useId();
  useLayoutEffect(() => {
    if (input.current) {
      input.current.style.height = "auto";
      input.current.style.height = `${Math.min(input.current.scrollHeight, 192)}px`;
    }
  }, [value]);
  const canSend =
    (!!value.trim() || attachments.some((item) => item.status === "ready")) &&
    !attachmentBlocked &&
    !busy &&
    !waiting &&
    !disabled;
  return (
    <form
      aria-label="Send a message"
      onDragOver={(event) => {
        if (onFiles && event.dataTransfer.types.includes("Files"))
          event.preventDefault();
      }}
      onDrop={(event) => {
        if (!onFiles || event.dataTransfer.files.length === 0) return;
        event.preventDefault();
        if (!disabled) onFiles(Array.from(event.dataTransfer.files));
      }}
      onSubmit={(event) => {
        event.preventDefault();
        if (canSend) onSubmit();
      }}
      className="rounded-2xl border border-border bg-background p-2 transition-colors focus-within:border-ring motion-reduce:transition-none"
    >
      {attachments.length > 0 && (
        <ComposerAttachments
          items={attachments}
          onRemove={onRemoveAttachment ?? (() => {})}
          onRetry={onRetryAttachment ?? (() => {})}
        />
      )}
      {attachmentError && (
        <p role="alert" className="px-2 pb-2 text-xs text-destructive">
          {attachmentError}
        </p>
      )}
      <Textarea
        ref={input}
        aria-label="Message"
        aria-describedby={hint}
        rows={1}
        value={value}
        disabled={disabled}
        placeholder={placeholder}
        onChange={(event) => onChange(event.target.value)}
        onPaste={(event) => {
          if (onFiles && event.clipboardData.files.length > 0) {
            event.preventDefault();
            if (!disabled) onFiles(Array.from(event.clipboardData.files));
          }
        }}
        onCompositionStart={() => {
          composing.current = true;
        }}
        onCompositionEnd={() => {
          composing.current = false;
        }}
        onKeyDown={(event) => {
          if (
            event.key === "Enter" &&
            !event.shiftKey &&
            !event.nativeEvent.isComposing &&
            !composing.current &&
            event.keyCode !== 229
          ) {
            event.preventDefault();
            if (canSend) onSubmit();
          }
        }}
      />
      <div className="flex min-h-7 items-center justify-end gap-2 pt-1">
        {onFiles && (
          <ComposerAttachmentPicker
            accept={attachmentAccept}
            disabled={disabled}
            onFiles={onFiles}
          />
        )}
        <p id={hint} className="sr-only">
          {waiting ? (
            "Waiting for your response"
          ) : busy ? (
            "You can write your next message"
          ) : (
            <>
              <span className="hidden sm:inline">Enter to send · </span>Shift +
              Enter for a new line
            </>
          )}
        </p>
        {busy && !waiting && onStop ? (
          <Button
            aria-label={cancelling ? "Stopping run" : "Stop run"}
            title="Stop run"
            variant="primary"
            disabled={cancelling || disabled}
            onClick={onStop}
            className="size-7 min-h-7 rounded-lg px-0 [@media(pointer:coarse)]:size-9"
          >
            <ChatIcon
              icon={Square}
              size={12}
              className="shrink-0"
              fill="currentColor"
              aria-hidden="true"
            />
          </Button>
        ) : (
          <Button
            type="submit"
            variant="primary"
            disabled={!canSend}
            aria-label="Send message"
            title="Send message"
            className="size-7 min-h-7 rounded-lg px-0 [@media(pointer:coarse)]:size-9"
          >
            <ChatIcon
              icon={ArrowUp}
              size={18}
              className="shrink-0"
              aria-hidden="true"
            />
          </Button>
        )}
      </div>
    </form>
  );
}

