import { FileText, ExternalLink } from "lucide-react";
import { ChatIcon } from "./icon";
import type { RenderContentBlock } from "@agentdock-ai/ui-core";
import { StreamingText } from "./streaming-text";
import { Reasoning } from "./reasoning";
import { ImageAttachment } from "./image-attachment";
import { safeUrl, formatJson } from "./utils";
export function MessageContent({
  blocks,
  showReasoning,
}: {
  blocks: readonly RenderContentBlock[];
  showReasoning: boolean;
}) {
  return (
    <div className="min-w-0 space-y-3">
      {blocks.map((block) => {
        if (block.type === "text")
          return (
            <StreamingText
              key={block.id}
              text={block.text}
              active={block.state === "streaming"}
            />
          );
        if (block.type === "reasoning")
          return showReasoning ? (
            <Reasoning
              key={block.id}
              text={block.text}
              active={block.state === "streaming"}
            />
          ) : null;
        if (block.type === "custom")
          return (
            <details
              key={block.id}
              className="rounded-lg border border-border text-sm"
            >
              <summary className="min-h-10 cursor-pointer px-3 py-2 outline-none focus-visible:ring-2 focus-visible:ring-ring">
                {block.name || "Additional content"}
              </summary>
              <pre
                tabIndex={0}
                className="max-h-64 overflow-auto whitespace-pre-wrap border-t border-border p-3 font-mono text-xs leading-6 [overflow-wrap:anywhere]"
              >
                {formatJson(block.data)}
              </pre>
            </details>
          );
        const url = safeUrl(block.url);
        if (block.type === "image" && url && /^https?:/i.test(url))
          return <ImageAttachment key={`${block.id}:${url}`} url={url} />;
        const label =
          block.type === "citation"
            ? block.title || "View source"
            : block.type === "file"
              ? block.name || "File"
              : `${block.type[0]?.toUpperCase()}${block.type.slice(1)}`;
        return (
          <div
            key={block.id}
            className="flex max-w-full items-center gap-2 rounded-lg border border-border px-3 py-2.5 text-sm text-muted-foreground"
          >
            <ChatIcon
              icon={FileText}
              size={16}
              aria-hidden="true"
              className="shrink-0"
            />
            {url ? (
              <a
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                className="flex min-w-0 items-center gap-2 rounded-sm underline underline-offset-4 outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <span className="[overflow-wrap:anywhere]">{label}</span>
                <ChatIcon
                  icon={ExternalLink}
                  size={13}
                  className="shrink-0"
                  aria-hidden="true"
                />
              </a>
            ) : (
              <span>{label} · Preview unavailable</span>
            )}
          </div>
        );
      })}
    </div>
  );
}

import type { JsonValue, RenderModel } from "@agentdock-ai/ui-core";
import { Message } from "./message";
import { ToolTimeline } from "./tool-timeline";
import { ApprovalCard } from "./approval-card";
import { ThinkingIndicator } from "./thinking-indicator";
import { ErrorState } from "./error-state";
export function MessageList({
  model,
  thinking = false,
  showReasoning,
  canRespond,
  respondingTo,
  approvalError,
  onRespond,
}: {
  model: RenderModel;
  thinking?: boolean;
  showReasoning: boolean;
  canRespond: boolean;
  respondingTo: string | null;
  approvalError?: string;
  onRespond: (interruptId: string, decisions: readonly JsonValue[]) => void;
}) {
  return (
    <div className="flex min-w-0 flex-col gap-7">
      {model.turns.map((turn) => (
        <div
          key={
            turn.items.find(
              (item) => item.type === "message" && item.role === "user",
            )?.id ?? turn.id
          }
          className="flex min-w-0 flex-col gap-4"
          data-turn={turn.id}
        >
          {turn.items.map((item) => {
            switch (item.type) {
              case "message":
                return (
                  <Message
                    key={item.id}
                    message={item}
                    showReasoning={showReasoning}
                    showActions={
                      turn.items
                        .filter(
                          (i) => i.type === "message" && i.role === "assistant",
                        )
                        .at(-1)?.id === item.id
                    }
                  />
                );
              case "tool-call":
                return <ToolTimeline key={item.id} tools={[item]} />;
              case "tool-timeline":
                return <ToolTimeline key={item.id} tools={item.tools} />;
              case "approval":
                return (
                  <ApprovalCard
                    key={item.id}
                    approval={item.approval}
                    enabled={canRespond && turn.state === "waiting"}
                    error={approvalError}
                    pending={respondingTo === item.approval.interruptId}
                    onRespond={(decisions) =>
                      onRespond(item.approval.interruptId, decisions)
                    }
                  />
                );
              case "error":
                return <ErrorState key={item.id} {...item.error} />;
            }
          })}
          {thinking && turn === model.turns.at(-1) && (
            <ThinkingIndicator
              label={
                turn.items.some(
                  (item) =>
                    item.type === "message" &&
                    item.role === "assistant" &&
                    item.blocks.some(
                      (block) => block.type === "text" && block.text.trim(),
                    ),
                )
                  ? "working"
                  : "thinking"
              }
            />
          )}
          {(turn.state === "stopped" || turn.transportState === "stopped") && (
            <p className="text-xs text-muted-foreground">
              Stopped · Your partial answer is preserved.
            </p>
          )}
        </div>
      ))}
    </div>
  );
}

import type { RenderMessageItem } from "@agentdock-ai/ui-core";
import { MessageContent } from "./message-content";
import { ChatActionBar } from "./chat-action-bar";
import { ToolMessage } from "./tool-message";
export function Message({
  message,
  showReasoning,
  showActions = true,
}: {
  message: RenderMessageItem;
  showReasoning: boolean;
  showActions?: boolean;
}) {
  if (message.role === "tool") return <ToolMessage message={message} />;
  const user = message.role === "user";
  const blocks = showReasoning
    ? message.blocks
    : message.blocks.filter((b) => b.type !== "reasoning");
  if (!blocks.length) return null;
  const images = user ? blocks.filter((block) => block.type === "image") : [];
  const body = user ? blocks.filter((block) => block.type !== "image") : blocks;
  const answer = blocks
    .flatMap((b) => (b.type === "text" ? [b.text] : []))
    .join("\n\n");
  return (
    <article
      data-role={message.role}
      data-message-id={message.id}
      aria-label={user ? "You" : "Assistant"}
      className={
        user
          ? "ml-auto flex min-w-0 max-w-[90%] flex-col items-end gap-2 sm:max-w-[85%]"
          : "group/message min-w-0 w-full px-2"
      }
    >
      {user ? (
        <>
          {images.length > 0 && (
            <div
              aria-label="Attached images"
              className="flex max-w-full flex-wrap justify-end gap-2"
            >
              {images.map((block) => (
                <MessageContent
                  key={block.id}
                  blocks={[block]}
                  showReasoning={showReasoning}
                />
              ))}
            </div>
          )}
          {body.length > 0 && (
            <div className="min-w-0 max-w-full rounded-2xl bg-muted px-4 py-2 text-[14px] leading-6 [overflow-wrap:anywhere]">
              {body.map((block) =>
                block.type === "text" ? (
                  <span key={block.id} className="whitespace-pre-wrap">
                    {block.text}
                  </span>
                ) : (
                  <MessageContent
                    key={block.id}
                    blocks={[block]}
                    showReasoning={showReasoning}
                  />
                ),
              )}
            </div>
          )}
        </>
      ) : (
        <MessageContent blocks={blocks} showReasoning={showReasoning} />
      )}
      {!user && showActions && message.state !== "streaming" && answer && (
        <ChatActionBar text={answer} />
      )}
    </article>
  );
}

